			{30, 24 - 9},
			{12, 24 - 9},
			{48, 24},
			{30, 24 + 9},
			{12, 24 + 9},
			{48, 24 + 18}
		};
		case 8: return new int[][] {
			{48, 24 - 18},
			{30, 24 - 18},
			{12, 24 - 9},
			{48, 24},
			{30, 24},
			{12, 24 + 9},
			{48, 24 + 18},
