			{30, 24 - 18},
			{12, 24 - 18},
			{48, 24},
			{30, 24},
			{12, 24},
			{48, 24 + 18},
			{30, 24 + 18},
			{12, 24 + 18}
		};
		}

		int[][] slots = new int[count][2];

		for(int i = 0; i < count; i++) {
			slots[i] = new int[] {i % 4 * 18, i / 4 * 18};
		}

		return slots;
	}

	public static int[][] getOutputCoords(int count) {

		switch(count) {
